import { data, checkPermission, TakaroUserError } from '@takaro/helpers';
import { JAIL_KEY, RELEASE_KEY, positionOf, setPoint, requireManage } from './jail-helpers.js';

async function main() {
  requireManage(checkPermission);

  const point = String(data.arguments.point ?? 'jail').toLowerCase();
  if (point !== 'jail' && point !== 'release') {
    throw new TakaroUserError("Use 'jail' or 'release', for example: setjail release");
  }

  const position = positionOf(data.pog);
  if (!position) {
    throw new TakaroUserError('Your position is not known yet. Move a bit and try again in a minute.');
  }

  await setPoint(point === 'jail' ? JAIL_KEY : RELEASE_KEY, position);
  const rounded = `${Math.round(position.x)}, ${Math.round(position.y)}, ${Math.round(position.z)}`;
  await data.player.pm(
    point === 'jail' ? `Jail set at ${rounded}.` : `Release point set at ${rounded}.`,
  );
}

await main();

import { data, checkPermission, TakaroUserError } from '@takaro/helpers';
import {
  JAIL_KEY,
  getPoint,
  getPrefix,
  getRecord,
  saveRecord,
  positionOf,
  findPog,
  teleport,
  assignJailedRole,
  pmPlayer,
  broadcast,
  playerName,
  formatRemaining,
  requireManage,
} from './jail-helpers.js';

async function main() {
  requireManage(checkPermission);
  const { arguments: args, module: mod } = data;
  const target = args.target;
  const minutes = Number(args.minutes);
  const reason = String(args.reason ?? '').trim() || 'No reason given';
  const prefix = await getPrefix();

  if (!Number.isInteger(minutes) || minutes < 0) {
    throw new TakaroUserError(`Minutes must be a whole number of 0 or more. Usage: ${prefix}jail <player> <minutes> <reason>`);
  }
  if (minutes > mod.userConfig.maxMinutes) {
    throw new TakaroUserError(`The maximum jail time is ${mod.userConfig.maxMinutes} minutes.`);
  }
  if (target.playerId === data.pog.playerId) {
    throw new TakaroUserError('You cannot jail yourself.');
  }

  const jail = await getPoint(JAIL_KEY);
  if (!jail) {
    throw new TakaroUserError(`No jail set yet. Stand in the jail and use ${prefix}setjail first.`);
  }

  const name = await playerName(target.playerId);
  const existing = await getRecord(target.playerId);
  if (existing && existing.status === 'jailed') {
    throw new TakaroUserError(`${name} is already jailed (${formatRemaining(existing)} left). Use ${prefix}unjail ${name} first.`);
  }

  const pog = (await findPog(target.playerId)) ?? target;
  const online = Boolean(pog.online);

  // Teleport first: if this game cannot teleport, nobody gets jailed.
  if (online) {
    try {
      await teleport(target.playerId, jail);
    } catch (err) {
      console.log(`Teleport failed: ${err?.message ?? err}`);
      throw new TakaroUserError(
        `Could not teleport ${name}. This game or connector may not support teleporting players. ${name} was not jailed.`,
      );
    }
  }

  const now = new Date();
  const record = {
    status: 'jailed',
    name,
    reason,
    by: data.player.name,
    startedAt: now.toISOString(),
    until: minutes === 0 ? null : new Date(now.getTime() + minutes * 60000).toISOString(),
    returnTo: existing?.returnTo ?? positionOf(pog),
    roleId: null,
  };
  if (await assignJailedRole(target.playerId)) {
    record.roleId = mod.userConfig.jailedRoleId;
  }
  await saveRecord(target.playerId, record);

  const duration = minutes === 0 ? 'until released by staff' : `for ${formatRemaining(record, now)}`;
  if (online && pog.gameId) {
    await pmPlayer(pog.gameId, `You have been jailed ${duration}. Reason: ${reason}. Type ${prefix}jailtime to see time left.`);
  }
  await broadcast(`${name} was jailed ${duration}. Reason: ${reason}`);
  await data.player.pm(
    online
      ? `${name} jailed ${duration}.`
      : `${name} is offline. They are jailed ${duration} and will be put in jail when they join.`,
  );
}

await main();

import { data, checkPermission, TakaroUserError } from '@takaro/helpers';
import { getRecord, findPog, releasePlayer, broadcast, playerName, requireManage } from './jail-helpers.js';

async function main() {
  requireManage(checkPermission);
  const target = data.arguments.target;
  const name = await playerName(target.playerId);

  const record = await getRecord(target.playerId);
  if (!record || record.status !== 'jailed') {
    throw new TakaroUserError(`${name} is not in jail.`);
  }

  const pog = (await findPog(target.playerId)) ?? target;
  const result = await releasePlayer(record, {
    online: Boolean(pog.online),
    gameId: pog.gameId,
    reasonText: `Released by ${data.player.name}.`,
  });

  await broadcast(`${name} was released from jail.`);
  await data.player.pm(
    result === 'released'
      ? `${name} has been released.`
      : `${name} has been released. They will be moved out of jail when they are online.`,
  );
}

await main();

import { data, checkPermission } from '@takaro/helpers';
import { listRecords, formatRemaining, requireManage } from './jail-helpers.js';

async function main() {
  requireManage(checkPermission);
  const records = (await listRecords()).filter((r) => r.status === 'jailed');

  if (records.length === 0) {
    await data.player.pm('Nobody is in jail.');
    return;
  }

  await data.player.pm(`In jail (${records.length}):`);
  for (const r of records) {
    await data.player.pm(`- ${r.name}: ${formatRemaining(r)} left. Reason: ${r.reason} (by ${r.by})`);
  }
}

await main();

import { data } from '@takaro/helpers';
import { getRecord, formatRemaining } from './jail-helpers.js';

async function main() {
  const record = await getRecord(data.pog.playerId);
  if (!record || record.status !== 'jailed') {
    await data.player.pm('You are not in jail.');
    return;
  }
  const left = record.until === null ? formatRemaining(record) : `${formatRemaining(record)} left`;
  await data.player.pm(`You are in jail: ${left}. Reason: ${record.reason}`);
}

await main();

